import json
U="UMGToolSet.UMGToolSet."
O="editor_toolset.toolsets.object.ObjectTools."
A="editor_toolset.toolsets.asset.AssetTools."
def call(name,args):
    r=execute_tool(name,json.dumps(args));assert "returnValue" in r,(name,r)
    return r["returnValue"]
def ref(x):return x["refPath"] if isinstance(x,dict) else x
def read_tree(bp):return call(U+"GetWidgets",{"widgetBlueprint":bp})
def update(obj,values):
    schema=json.loads(call(O+"list_properties",{"instance":obj}));norm=lambda s:s.lower().replace("_","")
    actual={}
    for key,value in values.items():
        name=next((x for x in schema if norm(x)==norm(key)),None);assert name,(key,list(schema));actual[name]=value
    call(O+"get_properties",{"instance":obj,"properties":list(actual)})
    assert call(O+"set_properties",{"instance":obj,"values":json.dumps(actual)})
def run():
    asset="/Game/Gameplay/UI/V2/WBP_UIHUDExtras";bp={"refPath":asset+".WBP_UIHUDExtras"}
    assert not call(A+"is_dirty",{"asset_path":asset})
    initial=read_tree(bp);d={x["widgetName"]:x for x in initial["widgets"]}
    assert ref(d["HUDExtrasRoot"]["widgetClassPath"])=="/Script/UMG.CanvasPanel"
    groups=["ExtrasCataclysmBounds","ExtrasSwimBounds","ExtrasPassivesBounds","ExtrasBoosterBounds"]
    for name in groups:
        assert ref(d[name]["widgetClassPath"])=="/Script/UMG.SizeBox"
        assert ref(d[name]["parent"]) in [ref(d["HUDExtrasRoot"]["widget"]),ref(d["ExtrasFlowRows"]["widget"]) if "ExtrasFlowRows" in d else ""]
    created=[]
    for name,cls,parent in [("ExtrasFlowBounds","SizeBox","HUDExtrasRoot"),("ExtrasFlowScroll","ScrollBox","ExtrasFlowBounds"),("ExtrasFlowRows","WrapBox","ExtrasFlowScroll")]:
        if name not in d:
            d[name]=call(U+"AddWidget",{"widgetBlueprint":bp,"widgetClass":{"refPath":"/Script/UMG."+cls},"widgetDisplayName":name,"parentWidget":d[parent]["widget"]});created.append(name)
        else:
            assert ref(d[name]["widgetClassPath"])=="/Script/UMG."+cls and ref(d[name]["parent"])==ref(d[parent]["widget"])
    update(d["ExtrasFlowBounds"]["slot"],{"layoutData":{"offsets":{"left":38,"top":-276,"right":0,"bottom":0},"anchors":{"minimum":{"x":0,"y":1},"maximum":{"x":0,"y":1}},"alignment":{"x":0,"y":1}},"bAutoSize":True})
    update(d["ExtrasFlowScroll"]["widget"],{"allowOverscroll":False,"scrollbarThickness":{"x":6,"y":6},"alwaysShowScrollbar":False,"scrollBarVisibility":"Collapsed"})
    update(d["ExtrasFlowRows"]["widget"],{"bExplicitWrapSize":True,"innerSlotPadding":{"x":16,"y":16},"horizontalAlignment":"HAlign_Left"})
    moved=[]
    for index,name in enumerate(groups):
        if ref(d[name]["parent"])!=ref(d["ExtrasFlowRows"]["widget"]):
            assert call(U+"MoveWidget",{"widgetBlueprint":bp,"widget":d[name]["widget"],"newParent":d["ExtrasFlowRows"]["widget"],"childIndex":index});moved.append(name)
    final=read_tree(bp);nodes={x["widgetName"]:x for x in final["widgets"]}
    for name in groups:update(nodes[name]["slot"],{"horizontalAlignment":"HAlign_Fill","verticalAlignment":"VAlign_Top","padding":{"left":0,"top":0,"right":0,"bottom":0}})
    assert all(ref(nodes[x["widgetName"]]["widget"])==ref(x["widget"]) for x in initial["widgets"]),"Original widget identity changed"
    assert call(U+"CompileWidgetBlueprint",{"widgetBlueprint":bp})
    assert call(A+"save_assets",{"asset_paths":[asset]})
    catch="/Game/Gameplay/UI/V2/WBP_UICatch";cbp={"refPath":catch+".WBP_UICatch"}
    assert not call(A+"is_dirty",{"asset_path":catch})
    ctree=read_tree(cbp);picture=next(x for x in ctree["widgets"] if x["widgetName"]=="CatchIllustrationBounds")
    update(picture["slot"],{"horizontalAlignment":"HAlign_Center"})
    update({"refPath":catch+".Default__WBP_UICatch_C"},{"illustrationHeight":176})
    assert call(U+"CompileWidgetBlueprint",{"widgetBlueprint":cbp})
    assert call(A+"save_assets",{"asset_paths":[catch]})
    return {"created":created,"movedExisting":moved,"originalWidgetIdentitiesPreserved":True,"catchIllustration":"Centered, height176; width adapts to69% card width"}
